}

Method.Source:
/// <summary>
/// Query ranges
/// </summary>
/// <param name = "qbdsSalesLine">QueryBuildDataSource</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_metSalesTabel">METSalesTable</param>
public void queryRange(QueryBuildDataSource qbdsSalesLine, SalesLine _salesLine, METSalesTable _metSalesTabel)
{
    METSalesLine metSalesLine = _salesLine.metSalesLine();
    METOriginalInvoice   originalInvoice;
    QueryBuildDataSource qbdsCustInvoiceTrans;

    if (metSalesLine.InvoiceNumber && metSalesLine.InvoiceLineNumber)
    {
        qbdsCustInvoiceTrans = qbdsSalesLine.addDataSource(tableNum(CustInvoiceTrans));
        qbdsCustInvoiceTrans.joinMode(JoinMode::InnerJoin);
        qbdsCustInvoiceTrans.addLink(fieldNum(SalesLine, InventTransId), fieldNum(CustInvoiceTrans, InventTransId));
        qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, InvoiceId)).value(metSalesLine.InvoiceNumber);
        qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, LineNum)).value(queryValue(metSalesLine.InvoiceLineNumber));
    }
    else if (_metSalesTabel.OriginalInvoice)
    {
        boolean isSalesId, isInvoiceId;
        originalInvoice = _metSalesTabel.OriginalInvoice;

        isInvoiceId = CustInvoiceTrans::existByInvoiceIdAndItemId(originalInvoice, _salesLine.ItemId) ? true : false;

        if (!isInvoiceId)
        {
            isSalesId = SalesTable::exist(originalInvoice) ? true : false;
        }

        qbdsCustInvoiceTrans = qbdsSalesLine.addDataSource(tableNum(CustInvoiceTrans));
        qbdsCustInvoiceTrans.joinMode(JoinMode::InnerJoin);
        qbdsCustInvoiceTrans.addLink(fieldNum(SalesLine, InventTransId), fieldNum(CustInvoiceTrans, InventTransId));

        if (isInvoiceId)
        {
            QueryBuildRange qbrInvoice = qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, InvoiceId));
            qbrInvoice.value(originalInvoice);
        }
        else if (isSalesId)
        {
            QueryBuildRange qbrSalesId = qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, SalesId));
            qbrSalesId.value(originalInvoice);
        }

        qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, ItemId)).value(_salesLine.ItemId);
    }
}

/// <summary>
/// assig return values
/// </summary>
/// <param name = "_priceComponent">METSalesLinePriceComponent</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_tmpTable">METSalesLinePriceComponentTmp</param>
public void setValues(METSalesLinePriceComponent _priceComponent,
                  SalesLine _salesLine,
                  METSalesLinePriceComponentTmp _tmpTable,
                  SalesLine _orgSalesLine)
{
    real convFactor = 1;

    if (_orgSalesLine.SalesUnit !=  _salesLine.SalesUnit)
    {
        convFactor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesLine.itemId,
                                                                        _salesLine.InventDimId,
                                                                        1,
                                                                        _orgSalesLine.SalesUnit,
                                                                        _salesLine.SalesUnit,
                                                                        NoYes::Yes);
        tmpTable.Value = convFactor ? -1 * (_priceComponent.Value / convFactor) : -1 * (_priceComponent.Value);

        ttsbegin;
        _salesLine.selectForUpdate(true);
        _salesLine.SalesPrice = _orgSalesLine.SalesPrice / convFactor;
        _salesLine.LineDisc = _orgSalesLine.LineDisc / convFactor;
        _salesLine.LineAmount = _salesLine.calcLineAmount();
        _salesLine.update();
        ttscommit;
    }
    else
    {
        tmpTable.Value = -1 * _priceComponent.Value;
    }

    SalesQty quantity = (_salesLine.SalesStatus == SalesStatus::Invoiced) && SalesParmLine::isCWClaimCreditApplicable(_salesLine)
    ? _salesLine.metSalesLine().CWReturnWeight
    : _salesLine.ExpectedRetQty;

    tmpTable.ExtValue = -1 * (tmpTable.Value * (quantity));
}
